require __DIR__ . '/bootstrap.php';
$user=requireLogin();if($_SERVER['REQUEST_METHOD']!=='POST')jsonResponse(false,'Method tidak diizinkan.',null,405);if(!hash_equals($_SESSION['csrf']??'',(string)($_POST['csrf']??'')))jsonResponse(false,'CSRF token tidak valid.',null,419);$orderId=(int)($_POST['order_id']??0);$file=$_FILES['proof_image']??null;if(!$file||$file['error']!==UPLOAD_ERR_OK||$file['size']>3*1024*1024)jsonResponse(false,'File bukti pembayaran tidak valid.',null,422);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$extensions=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($extensions[$mime]))jsonResponse(false,'Format file harus JPG, PNG, atau WEBP.',null,422);$pdo=db();$stmt=$pdo->prepare('SELECT id FROM orders WHERE id=? AND user_id=?');$stmt->execute([$orderId,$user['id']]);if(!$stmt->fetch())jsonResponse(false,'Pesanan tidak ditemukan.',null,404);$name='payment-'.bin2hex(random_bytes(12)).'.'.$extensions[$mime];$path=__DIR__.'/../uploads/'.$name;if(!move_uploaded_file($file['tmp_name'],$path))jsonResponse(false,'Gagal menyimpan file.',null,500);$pdo->prepare('UPDATE payments SET proof_image=?,payment_status="waiting_verification" WHERE order_id=? ORDER BY id DESC LIMIT 1')->execute([$name,$orderId]);$pdo->prepare('UPDATE orders SET payment_status="waiting_verification" WHERE id=?')->execute([$orderId]);jsonResponse(true,'Bukti pembayaran dikirim.');
